class VcfAuthError : System.Exception {
    [int]$StatusCode
    [string]$ErrorCode
    [string]$ReferenceToken
    VcfAuthError([string]$message, [int]$statusCode, [string]$errorCode, [string]$referenceToken) : base($message) {
        $this.StatusCode = $statusCode
        $this.ErrorCode = $errorCode
        $this.ReferenceToken = $referenceToken
    }
}

class VcfForbiddenError : System.Exception {
    [int]$StatusCode
    [string]$ErrorCode
    [string]$ReferenceToken
    VcfForbiddenError([string]$message, [int]$statusCode, [string]$errorCode, [string]$referenceToken) : base($message) {
        $this.StatusCode = $statusCode
        $this.ErrorCode = $errorCode
        $this.ReferenceToken = $referenceToken
    }
}

class VcfServerError : System.Exception {
    [int]$StatusCode
    [string]$ErrorCode
    [string]$ReferenceToken
    VcfServerError([string]$message, [int]$statusCode, [string]$errorCode, [string]$referenceToken) : base($message) {
        $this.StatusCode = $statusCode
        $this.ErrorCode = $errorCode
        $this.ReferenceToken = $referenceToken
    }
}

# Every credential and token the module ever handles is registered here for the
# lifetime of the process and scrubbed from all exception text, so an appliance
# that echoes a secret back in an error envelope cannot leak it. Entries are
# never removed: a rotated or superseded token must stay redactable, and the
# login password must stay redactable long after Connect-VcfSddcManager returns.
$script:VcfKnownSecrets = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::Ordinal)

function Register-VcfSecret {
    param([string]$Value)
    if ([string]::IsNullOrEmpty($Value)) { return }
    $null = $script:VcfKnownSecrets.Add($Value)
    # Also register encoded spellings an error envelope might echo.
    $jsonForm = ConvertTo-Json -InputObject $Value -Compress
    $jsonInner = $jsonForm.Substring(1, $jsonForm.Length - 2)
    if (-not [string]::IsNullOrEmpty($jsonInner)) { $null = $script:VcfKnownSecrets.Add($jsonInner) }
    $urlForm = [System.Uri]::EscapeDataString($Value)
    if (-not [string]::IsNullOrEmpty($urlForm)) { $null = $script:VcfKnownSecrets.Add($urlForm) }
}

function Hide-VcfSecret {
    param([string]$Text)
    if ([string]::IsNullOrEmpty($Text) -or $script:VcfKnownSecrets.Count -eq 0) { return $Text }
    # Longest first so a secret that contains another secret is scrubbed whole.
    foreach ($secret in ($script:VcfKnownSecrets | Sort-Object -Property Length -Descending)) {
        $Text = $Text.Replace($secret, '[REDACTED]')
    }
    return $Text
}

function Read-VcfErrorEnvelope {
    param([string]$Content)
    $envelope = [pscustomobject]@{ ErrorCode = ''; Message = ''; ReferenceToken = '' }
    if ([string]::IsNullOrWhiteSpace($Content)) { return $envelope }
    try {
        $parsed = ConvertFrom-Json -InputObject $Content
    } catch {
        return $envelope
    }
    if ($parsed -isnot [System.Management.Automation.PSCustomObject]) { return $envelope }
    foreach ($field in @(@('ErrorCode', 'errorCode'), @('Message', 'message'), @('ReferenceToken', 'referenceToken'))) {
        $property = $parsed.PSObject.Properties[$field[1]]
        if ($null -ne $property -and $null -ne $property.Value) {
            $envelope.($field[0]) = [string]$property.Value
        }
    }
    return $envelope
}

